UPDATE profile SET address_en = COALESCE(NULLIF(address_en, ''), 'No. 100, Wenhua Road, Xitun District, Taichung City, Taiwan'), short_bio_en = COALESCE(NULLIF(short_bio_en, ''), 'Dr. Cheng-Chia Huang is an Associate Professor in the Department of Water Resources Engineering and Conservation at Feng Chia University. His research focuses on reservoir and river sediment transport, reservoir desilting, hydraulic model experiments, numerical simulation, field monitoring, artificial intelligence, image analysis, and digital twins for water resources management, disaster early warning, and engineering decision support.'), full_bio_en = COALESCE(NULLIF(full_bio_en, ''), 'Dr. Cheng-Chia Huang works on water resources engineering, reservoir and river sediment transport, disaster early warning, and sustainable development. His methods include hydraulic model experiments, numerical modeling, field monitoring, image analysis, artificial intelligence, and digital twins.\n\nFrom 2009 to 2018, he participated in 37 research and engineering projects at the Hydraulic Engineering Laboratory of National Taiwan University, gaining experience in hydraulic modeling, sediment transport, field monitoring, numerical simulation, and international technical cooperation. In recent years, he has further integrated data science and intelligent technologies for sediment concentration prediction, urban inundation detection, disaster early warning, and watershed decision support.\n\nIn addition to research and teaching, he serves as Director of the Sustainability Division at Feng Chia University, contributing to university sustainability, cross-unit coordination, and international exchange.') WHERE id = 1;
UPDATE content_groups SET title_en = CASE key WHEN 'journal' THEN 'Journal Papers' WHEN 'conference' THEN 'Conference Papers' WHEN 'other' THEN 'Patents and Other Works' WHEN 'professional_service' THEN 'Professional Service' WHEN 'teaching' THEN 'Teaching and Talent Development' WHEN 'training' THEN 'Professional Training' WHEN 'visit_exchange' THEN 'International Visits and Technical Exchange' WHEN 'approved_cooperation' THEN 'Approved International Cooperation' WHEN 'developing_cooperation' THEN 'Cooperation in Discussion or Development' WHEN 'topics' THEN 'Main Research Topics' WHEN 'members' THEN 'Lab Members' WHEN 'activities' THEN 'Lab Activities' ELSE title END, short_title_en = CASE key WHEN 'journal' THEN 'Journal Papers' WHEN 'conference' THEN 'Conference Papers' WHEN 'other' THEN 'Patents and Other Works' WHEN 'professional_service' THEN 'Professional Service' WHEN 'teaching' THEN 'Teaching and Talent Development' WHEN 'training' THEN 'Professional Training' WHEN 'visit_exchange' THEN 'Visits and Exchange' WHEN 'approved_cooperation' THEN 'Approved Cooperation' WHEN 'developing_cooperation' THEN 'Developing Cooperation' WHEN 'topics' THEN 'Research Topics' WHEN 'members' THEN 'Lab Members' WHEN 'activities' THEN 'Lab Activities' ELSE short_title END WHERE title_en IS NULL;
UPDATE research_stats SET label_en = CASE label WHEN '期刊論文' THEN 'Journal Papers' WHEN '研討會論文' THEN 'Conference Papers' WHEN '發明專利' THEN 'Invention Patents' WHEN '主持計畫' THEN 'Projects Led' WHEN '受邀演講' THEN 'Invited Talks' WHEN '期刊審稿' THEN 'Journal Reviews' ELSE label END, note_en = note WHERE label_en IS NULL;
UPDATE invited_talks SET title_en = title, organization_en = organization, category_en = category WHERE title_en IS NULL;
UPDATE review_stats SET journal_en = journal WHERE journal_en IS NULL;
UPDATE academic_links SET name_en = name WHERE name_en IS NULL;
